"""Self-contained download server using inline data blob so no external navigation is blocked."""
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

B64 = """"""

PAGE = ("""<!doctype html>
<html lang="fa" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>دانلود فایل کامل دیدبان</title>
<style>
body { font-family: Tahoma, -apple-system, sans-serif; background: #f8fafc; color: #0f172a; margin: 0; padding: 20px; display: flex; align-items: center; justify-content: center; min-height: 90vh; }
.card { background: #ffffff; padding: 36px 28px; border-radius: 20px; box-shadow: 0 10px 25px rgba(0,0,0,0.08); text-align: center; max-width: 480px; width: 100%; border: 1px solid #e2e8f0; }
h1 { font-size: 20px; color: #4a2b82; margin-top: 0; margin-bottom: 8px; }
p { font-size: 13px; color: #64748b; line-height: 1.8; margin-bottom: 24px; }
.btn { display: block; width: 100%; box-sizing: border-box; background: #7c3aed; color: #ffffff; padding: 16px; border-radius: 12px; font-weight: bold; font-size: 15px; cursor: pointer; border: none; margin-bottom: 14px; text-decoration: none; box-shadow: 0 4px 12px rgba(124,58,237,0.3); }
.btn:hover { background: #6d28d9; }
.btn-alt { background: #0284c7; box-shadow: 0 4px 12px rgba(2,132,199,0.3); }
.btn-alt:hover { background: #0369a1; }
#msg { display: none; margin-top: 16px; padding: 12px; border-radius: 8px; background: #ecfdf5; color: #065f46; font-size: 13px; font-weight: bold; border: 1px solid #a7f3d0; }
</style>
</head>
<body>
<div class="card">
  <h1>دانلود فایل مستقل دیدبان</h1>
  <p>نسخهٔ کامل و مستقل HTML شامل تمام کدها، بدون عکس‌های نمونه، دارای بانک ۱۰ درس‌آموخته، چارت‌های PMO و نقشه حرارتی ۱۲ شرکت.</p>
  
  <button class="btn" onclick="downloadViaBlob()">⬇ کلیک کنید: ذخیره فایل HTML در سیستم</button>
  <a class="btn btn-alt" href="data:text/html;charset=utf-8;base64,""" + B64 + """" download="holding-inspection-dashboard.html">⬇ لینک پشتیبان مستقیم مرورگر</a>
  
  <div id="msg">✓ فایل با موفقیت دانلود شد! پوشه Downloads سیستم خود را بررسی کنید.</div>
</div>

<script>
const b64Data = """""" + B64 + """""";
function downloadViaBlob() {
  try {
    const byteChars = atob(b64Data);
    const byteNums = new Array(byteChars.length);
    for (let i = 0; i < byteChars.length; i++) {
      byteNums[i] = byteChars.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNums);
    const blob = new Blob([byteArray], {type: 'text/html;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'holding-inspection-dashboard.html';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 300);
    document.getElementById('msg').style.display = 'block';
  } catch(e) {
    alert('خطا: ' + e.message);
  }
}
</script>
</body>
</html>""").encode('utf-8')

class Downloads(BaseHTTPRequestHandler):
    def do_HEAD(self):
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.end_headers()

    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(PAGE)))
        self.end_headers()
        self.wfile.write(PAGE)

if __name__ == '__main__':
    ThreadingHTTPServer(('0.0.0.0', 8001), Downloads).serve_forever()
